pub fn parse_user_account(json: &str) -> Result<UserAccount, DecodeError> {
    wire::parse(json, decode_user_account)
}

/// Serializes a UserAccount to wire JSON text.
pub fn serialize_user_account(value: &UserAccount) -> String {
    encode_user_account(value).to_string()
}

/// Parses untrusted JSON text into a CredentialsRequest, or says where and why it is not one.
pub fn parse_credentials_request(json: &str) -> Result<CredentialsRequest, DecodeError> {
    wire::parse(json, decode_credentials_request)
}

/// Serializes a CredentialsRequest to wire JSON text.
pub fn serialize_credentials_request(value: &CredentialsRequest) -> String {
    encode_credentials_request(value).to_string()
}

/// Parses untrusted JSON text into a CredentialsResult, or says where and why it is not one.
pub fn parse_credentials_result(json: &str) -> Result<CredentialsResult, DecodeError> {
    wire::parse(json, decode_credentials_result)
}

/// Serializes a CredentialsResult to wire JSON text.
pub fn serialize_credentials_result(value: &CredentialsResult) -> String {
    encode_credentials_result(value).to_string()
}

/// Decode-then-encode by type name. Used only by the shared conformance runner.
pub fn conformance_round_trip(type_name: &str, value: &Value) -> Option<Result<Value, DecodeError>> {
    match type_name {
        "PermissionState" => Some(decode_permission_state(value, "$").map(|decoded| encode_permission_state(&decoded))),
        "UnavailableReason" => Some(decode_unavailable_reason(value, "$").map(|decoded| encode_unavailable_reason(&decoded))),
        "Requirement" => Some(decode_requirement(value, "$").map(|decoded| encode_requirement(&decoded))),
        "RelyingParty" => Some(decode_relying_party(value, "$").map(|decoded| encode_relying_party(&decoded))),
        "UserAccount" => Some(decode_user_account(value, "$").map(|decoded| encode_user_account(&decoded))),
        "CredentialsRequest" => Some(decode_credentials_request(value, "$").map(|decoded| encode_credentials_request(&decoded))),
        "CredentialsResult" => Some(decode_credentials_result(value, "$").map(|decoded| encode_credentials_result(&decoded))),
        _ => None,
    }
}
